"""Generates web/quran-rest.js: the rest of the Muṣḥaf, from the same verified sources as gen.js, loaded only when a student reaches it. Never edit its output by hand.
Order continues the traditional memorisation path: after Juzʾ ʿAmma, back from sūrah 77 toward al-Baqarah."""
import io, json, os, re, sys
ROOT = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(ROOT, 'sources')
OUT = os.path.join(ROOT, '..', 'web', 'quran-rest.js')
sys.path.insert(0, ROOT)
xml = io.open(os.path.join(SRC, 'tanzil-uthmani.xml'), encoding='utf-8').read()
cq = json.load(io.open(os.path.join(SRC, 'clearquran.json'), encoding='utf-8'))
cq = {s['number']: s for s in cq['surahs']}
src = io.open(os.path.join(ROOT, 'build_content.py'), encoding='utf-8').read()
# the same translation cleaning as the rest of the app
ns = {'re': re}
exec(src[src.index('def en_clean'):src.index('\n\n', src.index('def en_clean') + 20)], ns)
en_clean = ns['en_clean']
NAMES = {2: 'Al-Baqarah', 3: 'Āl ʿImrān', 4: 'An-Nisāʾ', 5: 'Al-Māʾidah', 6: 'Al-Anʿām', 7: 'Al-Aʿrāf', 8: 'Al-Anfāl', 9: 'At-Tawbah', 10: 'Yūnus', 11: 'Hūd', 12: 'Yūsuf', 13: 'Ar-Raʿd', 14: 'Ibrāhīm', 15: 'Al-Ḥijr', 16: 'An-Naḥl', 17: 'Al-Isrāʾ', 18: 'Al-Kahf', 19: 'Maryam', 20: 'Ṭā Hā', 21: 'Al-Anbiyāʾ', 22: 'Al-Ḥajj', 23: 'Al-Muʾminūn', 24: 'An-Nūr', 25: 'Al-Furqān', 26: 'Ash-Shuʿarāʾ', 27: 'An-Naml', 28: 'Al-Qaṣaṣ', 29: 'Al-ʿAnkabūt', 30: 'Ar-Rūm', 31: 'Luqmān', 32: 'As-Sajdah', 33: 'Al-Aḥzāb', 34: 'Sabaʾ', 35: 'Fāṭir', 36: 'Yā Sīn', 37: 'Aṣ-Ṣāffāt', 38: 'Ṣād', 39: 'Az-Zumar', 40: 'Ghāfir', 41: 'Fuṣṣilat', 42: 'Ash-Shūrā', 43: 'Az-Zukhruf', 44: 'Ad-Dukhān', 45: 'Al-Jāthiyah', 46: 'Al-Aḥqāf', 47: 'Muḥammad', 48: 'Al-Fatḥ', 49: 'Al-Ḥujurāt', 50: 'Qāf', 51: 'Adh-Dhāriyāt', 52: 'Aṭ-Ṭūr', 53: 'An-Najm', 54: 'Al-Qamar', 55: 'Ar-Raḥmān', 56: 'Al-Wāqiʿah', 57: 'Al-Ḥadīd', 58: 'Al-Mujādilah', 59: 'Al-Ḥashr', 60: 'Al-Mumtaḥanah', 61: 'Aṣ-Ṣaff', 62: 'Al-Jumuʿah', 63: 'Al-Munāfiqūn', 64: 'At-Taghābun', 65: 'Aṭ-Ṭalāq', 66: 'At-Taḥrīm', 67: 'Al-Mulk', 68: 'Al-Qalam', 69: 'Al-Ḥāqqah', 70: 'Al-Maʿārij', 71: 'Nūḥ', 72: 'Al-Jinn', 73: 'Al-Muzzammil', 74: 'Al-Muddaththir', 75: 'Al-Qiyāmah', 76: 'Al-Insān', 77: 'Al-Mursalāt'}
Q = {}
for m in re.finditer(r'<sura index="(\d+)" name="([^"]*)">(.*?)</sura>', xml, re.S):
    n = int(m.group(1))
    if n not in NAMES: continue
    ayat = re.findall(r'<aya index="(\d+)" text="([^"]*)"', m.group(3))
    trans = cq[n]['ayahs'] if 'ayahs' in cq[n] else cq[n]['verses']
    assert len(trans) == len(ayat), n
    Q[n] = {'n': n, 'name': NAMES[n], 'ar': m.group(2), 'en': cq[n]['title'], 'v': [[int(a), t, en_clean(trans[i]['text'])] for i, (a, t) in enumerate(ayat)]}
assert len(Q) == 76, len(Q)
order = list(range(77, 1, -1))
with io.open(OUT, 'w', encoding='utf-8', newline='\n') as f:
    f.write('/* Generated by tools/build_quran.py from verified sources. Never edit by hand. */\n')
    f.write('window.QURAN_REST=' + json.dumps({'order': order, 'q': Q}, ensure_ascii=False, separators=(',', ':')) + ';\n')
print('sūrahs', len(Q), 'āyāt', sum(len(s['v']) for s in Q.values()), 'KB', os.path.getsize(OUT) // 1024)
